class Solution:
    def searchRange(self, nums: list[int], target: int) -> list[int]:
        def bs(nums, target, search_left):
            l, r = 0, len(nums) - 1
            res = -1
            
            while l <= r:
                mid = (l + r) // 2

                if nums[mid] > target:
                    r = mid - 1
                
                elif nums[mid] < target:
                    l = mid + 1
                
                else:
                    res = mid
                    
                    if search_left:
                        r = mid - 1
                    
                    else:
                        l = mid + 1
            
