        int l = 0, r = height.size() - 1;

        while (l < r){
            int curr_area = min(height[l], height[r]) * (r-l);

            if (height[l] <= height[r]){
                l++;

            } else{
                r--;
            }

            largest_area = max(largest_area, curr_area);
        }

        return largest_area;
    }
};

