        stack<int> st;

        for (const string& op : operations){
            if (op == "+"){
                int last = st.top();
                st.pop();

                int second_last = st.top();

                st.push(last);
                st.push(last + second_last);

            } else if (op == "D"){
                st.push(st.top() * 2);

            } else if (op == "C"){
                st.pop();

            } else{
                st.push(stoi(op));
            }
        }

        int ans = 0;

        while (st.size() != 0){
            ans += st.top();
            st.pop();
        }

        return ans;
    }
};

